const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const L = data[idx++];
const C = data[idx++];
const P = data[idx++];

const black = Array.from({ length: L }, () => Array(C).fill(false));

for (let i = 0; i < P; i++) {
  const x = data[idx++] - 1;
  const y = data[idx++] - 1;
  black[x][y] = true;
}

const candidate = Array.from({ length: L }, () => Array(C).fill(false));
let count = 0;

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (black[r][c]) continue;

    const adjacentToBlack =
      (r > 0 && black[r - 1][c]) ||
      (r + 1 < L && black[r + 1][c]) ||
      (c > 0 && black[r][c - 1]) ||
      (c + 1 < C && black[r][c + 1]);

    if (adjacentToBlack) {
      candidate[r][c] = true;
      count++;
    }
  }
}

const matchRight = Array(L * C).fill(-1);
const dr = [-1, 1, 0, 0];
const dc = [0, 0, -1, 1];

function augment(r, c, visited) {
  for (let d = 0; d < 4; d++) {
    const nr = r + dr[d];
    const nc = c + dc[d];

    if (
      nr < 0 || nr >= L || nc < 0 || nc >= C ||
      !candidate[nr][nc]
    ) continue;

    const rightId = nr * C + nc;
    if (visited[rightId]) continue;
    visited[rightId] = true;

    if (
      matchRight[rightId] === -1 ||
      augment(Math.floor(matchRight[rightId] / C), matchRight[rightId] % C, visited)
    ) {
      matchRight[rightId] = r * C + c;
      return true;
    }
  }

  return false;
}

let matching = 0;

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (!candidate[r][c] || (r + c) % 2 !== 0) continue;
    if (augment(r, c, Array(L * C).fill(false))) matching++;
  }
}

console.log(count - matching);
